{
  "summary": "Anjali called to switch her expensive current plan to a cheaper option. The agent updated her account to the 499 rupee basic plan, but the customer was disappointed by the price as she expected 399 rupees. The change was processed and a confirmation SMS was arranged.",
  "reasons": [
    {
      "evidence": [
        {
          "turn_id": 2,
          "quote": "Mera current plan nahi chal raha hai, it is too expensive and I need to change it to a cheaper one."
        }
      ],
      "label": "plan_change",
      "confidence": 1.0,
      "rationale": "The customer explicitly states she wants to change her current expensive plan to a cheaper one."
    },
    {
      "evidence": [
        {
          "turn_id": 8,
          "quote": "Wait, 499? Maine toh suna tha it was 399. Why is it so expensive still?"
        }
      ],
      "label": "billing",
      "confidence": 0.8,
      "rationale": "The customer disputes the price of the plan during the modification."
    }
  ],
  "resolution": {
    "evidence": [
      {
        "turn_id": 11,
        "quote": "I will process the plan change and send a confirmation SMS to your phone."
      }
    ],
    "status": "resolved",
    "confidence": 0.9,
    "rationale": "The requested plan change was successfully processed by the agent, although the customer remained unhappy with the price."
  },
  "churn": {
    "evidence": [
      {
        "turn_id": 12,
        "quote": "SMS toh theek hai, but I am not happy with this price. This is totally unfair!"
      }
    ],
    "risk_score": 0.4,
    "flag": false,
    "rationale": "The customer expressed strong dissatisfaction with the price and service, but did not explicitly threaten to cancel or port out."
  }
}
